import{_ as e,c as t,o as i,a2 as a}from"./chunks/framework._4mWlOLd.js";const s=JSON.parse('{"title":"Attestation SDK - Use Cases","description":"","frontmatter":{"layout":"doc","title":"Attestation SDK - Use Cases"},"headers":[],"relativePath":"docs/attestify/usecases.md","filePath":"docs/attestify/usecases.md","lastUpdated":1741638736000}');const n=e({name:"docs/attestify/usecases.md"},[["render",function(e,s,n,o,r,l){return i(),t("div",null,s[0]||(s[0]=[a('<h1 id="attestation-sdk" tabindex="-1">Attestation SDK <a class="header-anchor" href="#attestation-sdk" aria-label="Permalink to &quot;Attestation SDK&quot;">​</a></h1><p><strong>Use Cases</strong><br><em>Real-world applications of secure attestation management</em></p><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><p>The <strong>Attestation SDK</strong>—with its Core SDK, Backend, and CLI—powers a range of scenarios requiring trust, verifiability, and scalability. Built for digital payment commitments and mutual attestations, it leverages HD wallets, cryptographic signatures, and a robust lifecycle to tackle challenges in finance, agreements, and beyond. Below are key use cases where Attestify shines, showing how it delivers value in practical settings.</p><hr><h2 id="_1-securing-digital-payment-commitments" tabindex="-1">1. Securing Digital Payment Commitments <a class="header-anchor" href="#_1-securing-digital-payment-commitments" aria-label="Permalink to &quot;1. Securing Digital Payment Commitments&quot;">​</a></h2><p><em>Ensuring trust in financial agreements</em></p><h3 id="scenario" tabindex="-1">Scenario <a class="header-anchor" href="#scenario" aria-label="Permalink to &quot;Scenario&quot;">​</a></h3><p>A bank and a corporate client need to agree on a digital payment commitment—say, a $10M trade settlement. Traditional systems rely on slow, centralized verification, risking delays or disputes.</p><h3 id="how-attestify-helps" tabindex="-1">How Attestify Helps <a class="header-anchor" href="#how-attestify-helps" aria-label="Permalink to &quot;How Attestify Helps&quot;">​</a></h3><ul><li><strong>Initiation</strong>: The bank (committer) creates a commitment via the SDK, specifying asset details (e.g., <code>$10M, USD</code>) and signs it with their HD wallet-derived key.</li><li><strong>Acknowledgment</strong>: The client (committee) verifies and countersigns using the CLI or backend API, moving the state to Acknowledged.</li><li><strong>Effectiveness</strong>: Both parties confirm the terms, transitioning to Effective with dual signatures.</li><li><strong>Discharge</strong>: Upon settlement, the bank discharges the commitment, cryptographically proving fulfillment.</li></ul><h3 id="benefits" tabindex="-1">Benefits <a class="header-anchor" href="#benefits" aria-label="Permalink to &quot;Benefits&quot;">​</a></h3><ul><li><strong>Speed</strong>: Instant state transitions replace days-long processes.</li><li><strong>Trust</strong>: Multi-signature verification ensures non-repudiation.</li><li><strong>Auditability</strong>: MongoDB logs every step for compliance (e.g., BAFT protocol).</li></ul><hr><h2 id="_2-mutual-attestations-for-business-agreements" tabindex="-1">2. Mutual Attestations for Business Agreements <a class="header-anchor" href="#_2-mutual-attestations-for-business-agreements" aria-label="Permalink to &quot;2. Mutual Attestations for Business Agreements&quot;">​</a></h2><p><em>Proving agreement between parties</em></p><h3 id="scenario-1" tabindex="-1">Scenario <a class="header-anchor" href="#scenario-1" aria-label="Permalink to &quot;Scenario&quot;">​</a></h3><p>Two companies negotiate a supply chain contract—e.g., delivering 100 tons of steel. They need a tamper-proof way to confirm terms without intermediaries.</p><h3 id="how-attestify-helps-1" tabindex="-1">How Attestify Helps <a class="header-anchor" href="#how-attestify-helps-1" aria-label="Permalink to &quot;How Attestify Helps&quot;">​</a></h3><ul><li><strong>CLI Workflow</strong>: Company A initiates the attestation (e.g., <code>node index.js create-commitment --assetName &quot;Steel&quot; --quantity 100</code>), storing it via the backend.</li><li><strong>Acknowledgment</strong>: Company B acknowledges it with their signature (<code>acknowledge-commitment</code>), verified by the SDK’s SignatureService.</li><li><strong>Acceptance</strong>: Company A accepts, locking in the deal.</li><li><strong>Discharge</strong>: After delivery, both sign to discharge, completing the cycle.</li></ul><h3 id="benefits-1" tabindex="-1">Benefits <a class="header-anchor" href="#benefits-1" aria-label="Permalink to &quot;Benefits&quot;">​</a></h3><ul><li><strong>Simplicity</strong>: The CLI abstracts complexity for non-technical users.</li><li><strong>Security</strong>: secp256k1 signatures prevent tampering.</li><li><strong>Flexibility</strong>: Custom derivation paths support multi-blockchain environments.</li></ul><hr><h2 id="_3-decentralized-finance-defi-workflows" tabindex="-1">3. Decentralized Finance (DeFi) Workflows <a class="header-anchor" href="#_3-decentralized-finance-defi-workflows" aria-label="Permalink to &quot;3. Decentralized Finance (DeFi) Workflows&quot;">​</a></h2><p><em>Powering trustless financial operations</em></p><h3 id="scenario-2" tabindex="-1">Scenario <a class="header-anchor" href="#scenario-2" aria-label="Permalink to &quot;Scenario&quot;">​</a></h3><p>A DeFi platform needs to manage collateral commitments between lenders and borrowers, integrating with wallets like MetaMask.</p><h3 id="how-attestify-helps-2" tabindex="-1">How Attestify Helps <a class="header-anchor" href="#how-attestify-helps-2" aria-label="Permalink to &quot;How Attestify Helps&quot;">​</a></h3><ul><li><strong>External Signing</strong>: The borrower initiates a commitment via the SDK, signing with MetaMask (<code>signWithMetaMask</code>).</li><li><strong>Backend Storage</strong>: The lender acknowledges it through the <code>/acknowledge-attestation</code> API, persisted in MongoDB.</li><li><strong>State Management</strong>: The SDK validates transitions (Initiated → Effective), ensuring collateral is locked.</li><li><strong>Release</strong>: After repayment, the discharge phase unlocks funds.</li></ul><h3 id="benefits-2" tabindex="-1">Benefits <a class="header-anchor" href="#benefits-2" aria-label="Permalink to &quot;Benefits&quot;">​</a></h3><ul><li><strong>Compatibility</strong>: Works with Web3 wallets out of the box.</li><li><strong>Scale</strong>: Handles high transaction volumes with lightweight design.</li><li><strong>Reliability</strong>: State validation prevents invalid transitions.</li></ul><hr><h2 id="_4-supply-chain-provenance" tabindex="-1">4. Supply Chain Provenance <a class="header-anchor" href="#_4-supply-chain-provenance" aria-label="Permalink to &quot;4. Supply Chain Provenance&quot;">​</a></h2><p><em>Tracking goods with verifiable commitments</em></p><h3 id="scenario-3" tabindex="-1">Scenario <a class="header-anchor" href="#scenario-3" aria-label="Permalink to &quot;Scenario&quot;">​</a></h3><p>A retailer wants to prove the origin of organic coffee beans to consumers, ensuring suppliers meet sustainability commitments.</p><h3 id="how-attestify-helps-3" tabindex="-1">How Attestify Helps <a class="header-anchor" href="#how-attestify-helps-3" aria-label="Permalink to &quot;How Attestify Helps&quot;">​</a></h3><ul><li><strong>Commitment Creation</strong>: The supplier attests to sourcing details (e.g., 500kg from Farm X) using the CLI.</li><li><strong>Verification</strong>: The retailer acknowledges via the backend, confirming receipt.</li><li><strong>Public Proof</strong>: The Effective state, signed by both, is shared as a QR code for consumer trust.</li><li><strong>Completion</strong>: Discharge occurs upon sale, closing the loop.</li></ul><h3 id="benefits-3" tabindex="-1">Benefits <a class="header-anchor" href="#benefits-3" aria-label="Permalink to &quot;Benefits&quot;">​</a></h3><ul><li><strong>Transparency</strong>: Cryptographic proof builds consumer confidence.</li><li><strong>Efficiency</strong>: Automates multi-party verification.</li><li><strong>Persistence</strong>: Backend logs ensure traceability.</li></ul><hr><h2 id="why-these-matter" tabindex="-1">Why These Matter <a class="header-anchor" href="#why-these-matter" aria-label="Permalink to &quot;Why These Matter&quot;">​</a></h2><p>These use cases highlight Attestify’s versatility:</p><ul><li><strong>Financial Trust</strong>: Secures payments and agreements with cryptographic rigor.</li><li><strong>Operational Efficiency</strong>: Automates workflows across industries.</li><li><strong>Developer Enablement</strong>: Simplifies integration into diverse systems.</li></ul><p>From banks to DeFi platforms to supply chains, Attestify turns complex attestation needs into streamlined, secure solutions.</p><hr><h2 id="see-it-in-action" tabindex="-1">See It in Action <a class="header-anchor" href="#see-it-in-action" aria-label="Permalink to &quot;See It in Action&quot;">​</a></h2><p>Check out the <a href="./demo">Demo</a> for a live example, or dive into <a href="./implementation">Implementation</a> to start building with Attestify.</p>',48)]))}]]);export{s as __pageData,n as default};
